from contextlib import contextmanager
from contextvars import ContextVar

import cv2
import numpy as np


def calc_bbox_mask_overlap_ratio(
    text_bbox: tuple[int, int, int, int],
    bubble_mask: np.ndarray,
) -> float:
    """Return the fraction of a text bounding box covered by a bubble mask."""
    x, y, box_w, box_h = map(int, text_bbox)
    x1, y1 = max(x, 0), max(y, 0)
    x2 = min(x + box_w, bubble_mask.shape[1])
    y2 = min(y + box_h, bubble_mask.shape[0])
    if x2 <= x1 or y2 <= y1:
        return 0.0
    return np.count_nonzero(bubble_mask[y1:y2, x1:x2]) / max(float(box_w * box_h), 1.0)


# Node Comics: labels are page working data; the optional budget is only for
# retained reference unions. Increasing it cannot evict those unions for labels.
_reference_masks = ContextVar('node_reference_masks', default=None)


@contextmanager
def reference_mask_cache(max_bytes, *, bubble_mask=None, components=None, record=None):
    state = {'mask': bubble_mask, 'labels': components[0] if components is not None else None,
             'stats': components[1] if components is not None else None,
             'unions': {}, 'entries': {}, 'rectangles': {}, 'bounds': {},
             'used': 0, 'max_bytes': max(0, int(max_bytes)), 'metrics': {}}
    token = _reference_masks.set(state)
    try:
        yield
    finally:
        if record is not None:
            for name, value in state['metrics'].items():
                record(name, value)
            record('render_reference_bytes', state['used'])
            record('render_labels_bytes', sum(value.nbytes for value in
                (state['labels'], state['stats']) if value is not None))
        state.clear()
        _reference_masks.reset(token)


def _metric(state, name, value=1):
    if state is not None:
        metrics = state['metrics']
        metrics[name] = metrics.get(name, 0) + value


def _reference_state(bubble_mask):
    state = _reference_masks.get()
    if state is not None and state['mask'] is not bubble_mask:
        for name in ('entries', 'rectangles', 'unions', 'bounds'):
            state[name].clear()
        state['labels'] = state['stats'] = None
        state['mask'], state['used'] = bubble_mask, 0
    return state


def cached_bubble_labels(bubble_mask):
    state = _reference_state(bubble_mask)
    if state is not None and state['labels'] is not None:
        _metric(state, 'render_label_hits')
        return state['labels']
    _, labels, stats, _ = cv2.connectedComponentsWithStats((bubble_mask > 0).astype(np.uint8), connectivity=8)
    labels.flags.writeable = stats.flags.writeable = False
    if state is not None:
        state['labels'], state['stats'] = labels, stats
        _metric(state, 'render_label_builds')
    return labels


def _region_labels(region, bubble_mask, label_map):
    h, w = bubble_mask.shape[:2]
    polygons = np.asarray(getattr(region, 'lines', []))
    if not polygons.size:
        polygons = np.asarray(region.min_rect)
    try:
        polygons = polygons.astype(np.int32).reshape(-1, 4, 2)
    except (TypeError, ValueError):
        return ()
    if not polygons.size or not h or not w:
        return ()
    polygons[..., 0] = np.clip(polygons[..., 0], 0, max(w - 1, 0))
    polygons[..., 1] = np.clip(polygons[..., 1], 0, max(h - 1, 0))
    x, y, width, height = cv2.boundingRect(polygons.reshape(-1, 2))
    region_mask = np.zeros((height, width), dtype=np.uint8)
    cv2.fillPoly(region_mask, list(polygons - np.array([x, y], dtype=np.int32)), 255)
    labels = np.unique(label_map[y:y + height, x:x + width][
        (region_mask > 0) & (bubble_mask[y:y + height, x:x + width] > 0)])
    return tuple(map(int, labels[labels > 0]))


def reference_cache_bytes(regions, bubble_mask, label_map):
    """Exact unique nonempty component combinations, not the paragraph count."""
    keys = {_region_labels(region, bubble_mask, label_map) for region in regions}
    return bubble_mask.nbytes * len(keys - {()})


def build_region_reference_mask(region, bubble_mask: np.ndarray, label_map: np.ndarray) -> np.ndarray:
    state = _reference_state(bubble_mask)
    if state is None or state['max_bytes'] < bubble_mask.size:
        return _build_region_reference_mask(region, bubble_mask, label_map)
    polygons = np.asarray(getattr(region, 'lines', []))
    if not polygons.size:
        polygons = np.asarray(region.min_rect)
    key = (polygons.shape, polygons.dtype.str, polygons.tobytes())
    cached = state['entries'].get(key)
    if cached is not None:
        _metric(state, 'render_reference_hits')
        return cached
    result = _build_region_reference_mask(region, bubble_mask, label_map)
    if id(result) in state['rectangles']:
        state['entries'][key] = result
    elif state['labels'] is not label_map and state['used'] + result.nbytes <= state['max_bytes']:
        result.flags.writeable = False
        state['entries'][key] = result
        state['rectangles'][id(result)] = None
        state['used'] += result.nbytes
    return result


def cached_largest_inscribed_rect(mask, calculate):
    state = _reference_masks.get()
    rectangles = state['rectangles'] if state is not None else {}
    key = id(mask)
    if key not in rectangles or mask.flags.writeable:
        return calculate(mask)
    if rectangles[key] is None:
        rectangles[key] = calculate(mask)
    else:
        _metric(state, 'render_rectangle_hits')
    return rectangles[key]


def reference_mask_bounds(mask):
    state = _reference_masks.get()
    if state is not None and id(mask) in state['rectangles']:
        return state['bounds'].get(id(mask))
    return None


def _build_region_reference_mask(region, bubble_mask: np.ndarray, label_map: np.ndarray) -> np.ndarray:
    labels = _region_labels(region, bubble_mask, label_map)
    state = _reference_masks.get()
    shared = state is not None and state['mask'] is bubble_mask and state['labels'] is label_map
    if shared and labels in state['unions']:
        _metric(state, 'render_reference_hits')
        return state['unions'][labels]
    _metric(state, 'render_reference_builds')
    bounds = None
    if shared and state['stats'] is not None:
        result = np.zeros(bubble_mask.shape[:2], dtype=np.uint8)
        for label in labels:
            x, y, width, height = map(int, state['stats'][label, :4])
            local = result[y:y + height, x:x + width]
            local[label_map[y:y + height, x:x + width] == label] = 255
            _metric(state, 'render_reference_roi_pixels', width * height)
        if labels:
            boxes = state['stats'][list(labels), :4]
            left, top = boxes[:, :2].min(axis=0)
            right, bottom = (boxes[:, :2] + boxes[:, 2:4]).max(axis=0)
            bounds = (int(left), int(top), int(right - left), int(bottom - top))
    else:
        # Foreign/relabelled input maps keep the native semantic fallback.
        result = np.isin(label_map, labels).astype(np.uint8) * 255
        _metric(state, 'render_reference_full_pixels', bubble_mask.size)
    if shared and labels and state['used'] + result.nbytes <= state['max_bytes']:
        result.flags.writeable = False
        state['unions'][labels] = result
        state['rectangles'][id(result)] = None
        state['bounds'][id(result)] = bounds
        state['used'] += result.nbytes
    return result
